using json=nlohmann::ordered_json;
struct protocol_error:std::runtime_error{using std::runtime_error::runtime_error;};
inline void require(bool ok,const char*message){if(!ok)throw protocol_error(message);}
inline void fields(const json&v,std::initializer_list<const char*>keys){require(v.is_object()&&v.size()==keys.size(),"DSpark operation fields mismatch");for(auto*k:keys)require(v.contains(k),"DSpark operation field missing");}
inline std::int32_t integer(const json&v,std::int32_t low,std::int32_t high){require(v.is_number_integer(),"DSpark integer required");if(v.is_number_unsigned())require(v.get<std::uint64_t>()<=static_cast<std::uint64_t>(high),"DSpark integer exceeds bound");auto n=v.get<std::int64_t>();require(n>=low&&n<=high,"DSpark integer outside bounds");return static_cast<std::int32_t>(n);}
inline std::string text(const json&v,std::size_t bound=128){require(v.is_string(),"DSpark string required");auto s=v.get<std::string>();require(s.size()<=bound&&s.find('\0')==std::string::npos,"DSpark string bound/NUL violation");return s;}
inline bool boolean(const json&v){require(v.is_boolean(),"DSpark boolean required");return v.get<bool>();}
inline std::vector<std::uint8_t>unhex(const json&v){auto s=text(v,8*1024*1024);require(s.size()%2==0,"DSpark hex extent differs");std::vector<std::uint8_t>b(s.size()/2);auto digit=[](char c)->unsigned{if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;throw std::runtime_error("DSpark hex digit invalid");};for(std::size_t i=0;i<b.size();++i)b[i]=static_cast<std::uint8_t>((digit(s[2*i])<<4)|digit(s[2*i+1]));return b;}
inline std::string hex(const void*data,std::size_t size){require(size<=8*1024*1024,"DSpark observed bytes exceed8MiB");constexpr char digits[]="0123456789abcdef";auto*b=static_cast<const unsigned char*>(data);std::string s(size*2,'\0');for(std::size_t i=0;i<size;++i){s[2*i]=digits[b[i]>>4];s[2*i+1]=digits[b[i]&15];}return s;}
inline llama_tokens tokens(const json&v,std::size_t cap=2048){require(v.is_array()&&v.size()<=cap,"DSpark token list exceeds bound");llama_tokens out;for(const auto&t:v)out.push_back(integer(t,0,1048576));return out;}
inline std::vector<std::int32_t>positions(const json&v,std::size_t count){require(v.is_array()&&v.size()==count,"DSpark positions extent differs");std::vector<std::int32_t>out;for(const auto&p:v)out.push_back(integer(p,0,131072));return out;}
inline std::string filename(const json&v){auto s=text(v,128);require(!s.empty()&&s.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-")==std::string::npos&&s.find("..") == std::string::npos,"DSpark output must be an owned plain filename");require(!std::filesystem::exists(s),"DSpark output already exists");return s;}
struct trace{
    std::set<std::string>names;std::vector<std::string>prefixes;std::mutex mutex;std::map<std::string,std::vector<std::uint8_t>>values;std::size_t bytes=0;std::atomic<bool>failed{false};
    bool selected(const std::string&name)const{if(names.count(name))return true;for(const auto&p:prefixes)if(name.rfind(p,0)==0)return true;return false;}
    static bool callback(ggml_tensor*t,bool ask,void*opaque)noexcept{auto&self=*static_cast<trace*>(opaque);try{if(ask)return t->type==GGML_TYPE_F32&&ggml_is_contiguous(t)&&self.selected(t->name);auto size=ggml_nbytes(t);std::lock_guard<std::mutex>guard(self.mutex);auto&out=self.values[t->name];require(size<=8*1024*1024&&self.bytes-out.size()+size<=8*1024*1024,"DSpark trace exceeded8MiB");self.bytes=self.bytes-out.size()+size;out.resize(size);ggml_backend_tensor_get(t,out.data(),0,size);return true;}catch(...){self.failed=true;return false;}}
};
struct spec_owner{common_speculative*value=nullptr;std::shared_ptr<void>draft,target;~spec_owner(){if(value)common_speculative_free(value);}};
struct sampler_owner{common_sampler*common=nullptr;llama_sampler*greedy=nullptr;std::shared_ptr<void>model;~sampler_owner(){if(common)common_sampler_free(common);if(greedy)llama_sampler_free(greedy);}};
struct stage_owner{llama_context*context=nullptr;std::shared_ptr<void>owner;std::vector<float>features;std::vector<std::int32_t>positions;~stage_owner(){if(context)llama_set_dspark_ctx(context,nullptr,0,0,nullptr);}};
struct binding{llama_context*context=nullptr;std::shared_ptr<void>owner;std::shared_ptr<sampler_owner>sampler;llama_seq_id sequence=0;~binding(){if(context)llama_set_sampler(context,sequence,nullptr);}};
inline bool handles(const std::string&op){static const std::set<std::string>names={"dspark-meta","dspark-context-info","model-vocabulary","capture-layers","causal-attention","dspark-stage","dspark-stage-clear","observe-decode","sampled-tokens","speculative-init","speculative-begin","speculative-process","speculative-draft","speculative-accept","speculative-needs-capture","speculative-release","speculative-stage","speculative-stats","common-sampler-new","common-sampler-sample","common-sampler-accept","common-sampler-free","common-sampler-sample-and-accept-n","greedy-sampler-new","context-set-sampler","model-tensor-info","model-tensor-file","model-output-identity","process-environment","process-environment-restore","trace-new","context-traces","observe-production","graph-allow-reuse","decode-output-logits"};return names.count(op)!=0;}
