    template<class T>std::shared_ptr<T>get(const std::map<std::uint64_t,std::shared_ptr<T>>&table,const json&id){auto value=integer(id,1,1000000);auto it=table.find(value);require(it!=table.end(),"unknown DSpark handle");return it->second;}
    static void setenv_raw(const std::string&key,const std::optional<std::string>&value){
#ifdef _WIN32
        require(_putenv_s(key.c_str(),value?value->c_str():"")==0,"native process environment update failed");
#else
        require(value?setenv(key.c_str(),value->c_str(),1)==0:unsetenv(key.c_str())==0,"native process environment update failed");
#endif
    }
public:
    ~state(){bindings.clear();specs.clear();stages.clear();for(auto frame=env_frames.rbegin();frame!=env_frames.rend();++frame)for(const auto&item:frame->second)try{setenv_raw(item.first,item.second);}catch(...){}for(const auto&item:original_env)try{setenv_raw(item.first,item.second);}catch(...){}}
    std::shared_ptr<trace>trace_handle(const json&id){return get(traces,id);}
