        if(op=="graph-allow-reuse"){fields(o,{"Op","Previous","Next","LiveRows","LiveWidth"});llama_dspark_ctx staged;staged.n_ctx_rows=integer(o.at("LiveRows"),0,2048);staged.n_embd_cap=integer(o.at("LiveWidth"),0,1048576);llm_graph_params previous{},next{};for(auto item:{std::make_pair(&previous,&o.at("Previous")),std::make_pair(&next,&o.at("Next"))}){fields(*item.second,{"HasContext","Rows","Width"});item.first->dspark_ctx=&staged;item.first->dspark_has_context=boolean(item.second->at("HasContext"));item.first->dspark_ctx_rows=integer(item.second->at("Rows"),0,2048);item.first->dspark_ctx_width=integer(item.second->at("Width"),0,1048576);}return json{{"AllowReuse",previous.allow_reuse(next)}};}
