        if(op=="capture-layers"){fields(o,{"Op","Context","Layers"});auto c=context(o.at("Context"));require(o.at("Layers").is_array()&&o.at("Layers").size()<=1024,"capture layers exceed1024");std::vector<int>layers;for(const auto&l:o.at("Layers"))layers.push_back(integer(l,-1,65535));llama_set_capture_layers(c->value,layers.data(),layers.size());return json{{"CaptureCount",llama_get_n_capture(c->value)}};}
