        if(op=="model-tensor-info"||op=="model-tensor-file"){fields(o,op=="model-tensor-info"?std::initializer_list<const char*>{"Op","Model","Names"}:std::initializer_list<const char*>{"Op","Model","Name","Output"});auto m=model(o.at("Model"));json list=op=="model-tensor-info"?o.at("Names"):json::array({o.at("Name")});require(list.is_array()&&list.size()<=128,"tensor name request exceeds128");json values=json::array();for(const auto&name:list){auto*t=m->value->get_tensor(text(name).c_str());if(!t){values.push_back(json{{"Name",name},{"Found",false}});continue;}json dimensions=json::array();for(auto n:t->ne)dimensions.push_back(n);json value{{"Name",name},{"Found",true},{"Type",static_cast<int>(t->type)},{"Dimensions",dimensions},{"Bytes",ggml_nbytes(t)}};if(op=="model-tensor-file"){auto output=filename(o.at("Output"));auto size=ggml_nbytes(t);require(size<=UINT64_C(4)*1024*1024*1024,"tensor input file exceeds4GiB");std::ofstream stream(output,std::ios::binary);require(bool(stream),"cannot create tensor observation file");stream.exceptions(std::ios::badbit|std::ios::failbit);std::vector<std::uint8_t>chunk(65536);for(std::size_t offset=0;offset<size;){auto count=std::min(chunk.size(),size-offset);ggml_backend_tensor_get(t,chunk.data(),offset,count);stream.write(reinterpret_cast<const char*>(chunk.data()),static_cast<std::streamsize>(count));offset+=count;}stream.close();value["DataFile"]=std::filesystem::absolute(output).string();}values.push_back(value);}return json{{"Tensors",values}};}
        if(op=="trace-new"){fields(o,{"Op","Names","Prefixes"});auto value=std::make_shared<trace>();require(o.at("Names").is_array()&&o.at("Names").size()<=64&&o.at("Prefixes").is_array()&&o.at("Prefixes").size()<=16,"trace filter counts exceed bounds");for(const auto&n:o.at("Names"))value->names.insert(text(n));for(const auto&p:o.at("Prefixes")){auto prefix=text(p);require(!prefix.empty(),"empty trace prefix unsupported");value->prefixes.push_back(prefix);}require(traces.size()<64,"trace handles exceed64");auto id=next++;traces.emplace(id,value);return json{{"Trace",id}};}
        if(op=="context-traces"){fields(o,{"Op","Trace"});auto trace=get(traces,o.at("Trace"));std::lock_guard<std::mutex>guard(trace->mutex);json values=json::array();for(const auto&v:trace->values)values.push_back(json{{"Name",v.first},{"DataHex",hex(v.second.data(),v.second.size())}});return json{{"Failed",trace->failed.load()},{"Values",values}};}
        if(op=="process-environment-restore"){fields(o,{"Op","Environment"});auto id=integer(o.at("Environment"),1,1000000);auto it=env_frames.find(id);require(it!=env_frames.end(),"unknown saved environment frame");for(const auto&v:it->second)setenv_raw(v.first,v.second);env_frames.erase(it);return nullptr;}
        fields(o,{"Op","Changes","Save"});require(op=="process-environment","unknown DSpark runtime operation");require(o.at("Changes").is_object()&&o.at("Changes").size()<=32,"environment changes exceed32");static const std::set<std::string>flags={"LLAMA_DSPARK_SNR_TWO_ROWS","LLAMA_DSPARK_BALANCED_OUTPUT","LLAMA_DSPARK_REUSE_MASK","LLAMA_DSPARK_GREEDY_IDS","LLAMA_DSPARK_SHARED_HEAD","DSPARK_TEST_NO_FA","DSPARK_TEST_TRACE","DSPARK_TEST_ORACLE","DSPARK_ORACLE_KLD","DSPARK_ORACLE_SAME_PATH","DSPARK_PARITY_CONTINUE","DSPARK_PARITY_ORACLE_SPLIT_PREFILL"};static const std::set<std::string>integers={"LLAMA_DSPARK_CORRECTION_PREFIX","DSPARK_FORWARD_ROWS","DSPARK_CORRECTION_ROWS","DSPARK_HEAD_TOP_K","DSPARK_TEST_HEAD_TOP_K","DSPARK_EVAL_BATCH","DSPARK_EVAL_CONTEXT","DSPARK_PARITY_ORACLE_ROWS"};std::map<std::string,std::optional<std::string>>saved,changes;for(const auto&v:o.at("Changes").items()){require(flags.count(v.key())||integers.count(v.key()),"environment key outside source allowlist");auto*before=std::getenv(v.key().c_str());saved[v.key()]=before?std::optional<std::string>(before):std::nullopt;if(!original_env.count(v.key()))original_env[v.key()]=saved[v.key()];if(v.value().is_null())changes[v.key()]=std::nullopt;else if(v.key()=="LLAMA_DSPARK_CORRECTION_PREFIX"&&v.value().is_string()){changes[v.key()]=text(v.value(),32);}else if(flags.count(v.key())){changes[v.key()]=boolean(v.value())?"1":"0";}else changes[v.key()]=std::to_string(integer(v.value(),0,1048576));}for(const auto&v:changes)setenv_raw(v.first,v.second);json id=nullptr;if(boolean(o.at("Save"))){id=next;env_frames.emplace(next++,std::move(saved));}return json{{"Environment",id}};
